{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const here = path.dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || path.join(here, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1)),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}

const page = await readFile(path.join(here, 'index.html'));

function sendJson(response, status, payload) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(payload));
}

async function readBody(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }

  if (request.method === 'GET' && url.pathname === '/api/projects') {
    const archived = url.searchParams.get('archived') === 'true' ? 1 : 0;
    const projects = database.prepare(`
      SELECT p.id, p.name, p.archived, COUNT(t.id) AS total_count,
        SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END) AS completed_count
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
    `).all(archived).map((project) => ({
      id: Number(project.id), name: project.name, archived: Boolean(project.archived),
      totalCount: Number(project.total_count), completedCount: Number(project.completed_count || 0),
    }));
    return sendJson(response, 200, projects);
  }

  if (request.method === 'POST' && url.pathname === '/api/projects') {
    const body = await readBody(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'GET' && projectMatch) {
    const project = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, { ...project, id: Number(project.id), archived: Boolean(project.archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }

  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (renameMatch && request.method === 'POST') {
    const id = Number(renameMatch[1]);
    const body = await readBody(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) return sendJson(response, 400, { error: 'Project name is required' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(id);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 400, { error: 'Archived project' });
    database.prepare('UPDATE projects SET name = ? WHERE id = ?').run(name, id);
    return sendJson(response, 200, { id, name });
  }

  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveMatch && request.method === 'POST') {
    const id = Number(archiveMatch[1]);
    const archived = archiveMatch[2] === 'archive' ? 1 : 0;
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archived, id);
    return result.changes ? sendJson(response, 200, { id, archived: Boolean(archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }

  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId)
      .map((task) => ({ ...task, id: Number(task.id), projectId: Number(task.projectId), completed: Boolean(task.completed) }));
    return sendJson(response, 200, tasks);
  }

  if (tasksMatch && request.method === 'POST') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 400, { error: 'Archived project' });
    const body = await readBody(request);
    const title = typeof body?.title === 'string' ? body.title.trim() : '';
    if (!title) return sendJson(response, 400, { error: 'Task title is required' });
    const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false });
  }

  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    const body = await readBody(request);
    if (typeof body?.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion state is required' });
    const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
    if (project?.archived) return sendJson(response, 400, { error: 'Archived project' });
    const result = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(body.completed ? 1 : 0, taskId, projectId);
    if (!result.changes) return sendJson(response, 404, { error: 'Task not found' });
    return sendJson(response, 200, { id: taskId, projectId, completed: body.completed });
  }

  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+\/?$/.test(url.pathname))) {
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return response.end(page);
  }
  response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { font-family: system-ui, sans-serif; color: #202938; background: #f5f7fa; }
    body { max-width: 760px; margin: 0 auto; padding: 48px 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form { display: flex; gap: 12px; margin-bottom: 24px; }
    input { flex: 1; min-width: 0; padding: 11px 12px; border: 1px solid #aeb8c5; border-radius: 6px; font: inherit; }
    button { padding: 10px 16px; border: 0; border-radius: 6px; background: #2457c5; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #1946a6; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-top: 1px solid #d7dde5; }
    .project-name { overflow-wrap: anywhere; }
    .task-row { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid #d7dde5; }
    .task-row label { overflow-wrap: anywhere; }
    .task-tools { display: flex; align-items: center; gap: 10px; margin: 24px 0 12px; }
    select { padding: 9px 10px; border: 1px solid #aeb8c5; border-radius: 6px; font: inherit; }
    #alert { color: #a32222; margin: 0 0 16px; }
    @media (max-width: 480px) { body { padding: 28px 16px; } form { flex-direction: column; } }
  </style>
</head>
<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapePath = (value) => encodeURIComponent(value);

    async function request(path, options) {
      const response = await fetch(path, options);
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Request failed');
      return data;
    }

    function projectRow(project, onChange) {
      const row = document.createElement('div');
      row.className = 'project-row';
      row.dataset.testid = 'project-row';
      const name = document.createElement('span');
      name.className = 'project-name';
      name.textContent = project.name;
      const open = document.createElement('button');
      open.type = 'button';
      open.textContent = 'Open project';
      open.addEventListener('click', () => {
        location.href = `/projects/${escapePath(project.id)}`;
      });
      const summary = document.createElement('span');
      summary.dataset.testid = 'project-summary';
      summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
      const change = document.createElement('button');
      change.type = 'button';
      change.textContent = project.archived ? 'Restore project' : 'Archive project';
      change.addEventListener('click', async () => {
        try {
          await request(`/api/projects/${escapePath(project.id)}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
          await onChange();
        } catch (error) { window.alert(error.message); }
      });
      row.append(name, summary, open, change);
      return row;
    }

    async function showList() {
      app.replaceChildren();
      const heading = document.createElement('h1');
      heading.textContent = 'Workboard';
      const form = document.createElement('form');
      const input = document.createElement('input');
      input.type = 'text';
      input.setAttribute('aria-label', 'Project name');
      const create = document.createElement('button');
      create.type = 'submit';
      create.textContent = 'Create project';
      form.append(input, create);
      const alert = document.createElement('p');
      alert.id = 'alert';
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      const list = document.createElement('section');
      list.setAttribute('aria-label', 'Projects');
      const filter = document.createElement('select');
      filter.setAttribute('aria-label', 'Project filter');
      for (const value of ['Active', 'Archived']) {
        const option = document.createElement('option'); option.value = value; option.textContent = value; filter.append(option);
      }
      async function loadProjects() {
        const projects = await request(`/api/projects?archived=${filter.value === 'Archived'}`);
        list.replaceChildren();
        for (const project of projects) list.append(projectRow(project, loadProjects));
      }
      filter.addEventListener('change', loadProjects);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          return;
        }
        try {
          const project = await request('/api/projects', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name }),
          });
          alert.hidden = true;
          alert.textContent = '';
          input.value = '';
          await loadProjects();
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      app.append(heading, filter, form, alert, list);
      await loadProjects();
    }

    async function showProject(id) {
      const project = await request(`/api/projects/${escapePath(id)}`);
      app.replaceChildren();
      const back = document.createElement('button');
      back.type = 'button';
      back.textContent = 'Projects';
      back.addEventListener('click', () => { location.href = '/'; });
      const heading = document.createElement('h1');
      heading.textContent = project.name;
      const archivedNotice = document.createElement('p');
      archivedNotice.textContent = project.archived ? 'Archived project' : '';
      archivedNotice.hidden = !project.archived;
      const renameForm = document.createElement('form');
      const renameInput = document.createElement('input');
      renameInput.type = 'text';
      renameInput.setAttribute('aria-label', 'New project name');
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename project';
      renameButton.disabled = project.archived;
      renameForm.append(renameInput, renameButton);
      const form = document.createElement('form');
      const input = document.createElement('input');
      input.type = 'text';
      input.setAttribute('aria-label', 'Task title');
      const create = document.createElement('button');
      create.type = 'submit';
      create.textContent = 'Create task';
      create.disabled = project.archived;
      form.append(input, create);
      const alert = document.createElement('p');
      alert.id = 'alert';
      alert.setAttribute('role', 'alert');
      alert.hidden = true;
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          return;
        }
        try {
          const updated = await request(`/api/projects/${escapePath(id)}/rename`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ name }),
          });
          project.name = updated.name;
          heading.textContent = updated.name;
          renameInput.value = '';
          alert.textContent = '';
          alert.hidden = true;
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      const tools = document.createElement('div');
      tools.className = 'task-tools';
      const filterLabel = document.createElement('label');
      filterLabel.textContent = 'Task filter';
      const filter = document.createElement('select');
      filter.setAttribute('aria-label', 'Task filter');
      for (const value of ['All', 'Open', 'Completed']) {
        const option = document.createElement('option');
        option.value = value;
        option.textContent = value;
        filter.append(option);
      }
      filterLabel.append(filter);
      tools.append(filterLabel);
      const list = document.createElement('section');
      list.setAttribute('aria-label', 'Tasks');
      let tasks = await request(`/api/projects/${escapePath(id)}/tasks`);

      function renderTasks() {
        list.replaceChildren();
        for (const task of tasks) {
          if (filter.value === 'Open' && task.completed) continue;
          if (filter.value === 'Completed' && !task.completed) continue;
          const row = document.createElement('div');
          row.className = 'task-row';
          row.dataset.testid = 'task-row';
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = task.completed;
          checkbox.disabled = project.archived;
          checkbox.setAttribute('aria-label', `Complete ${task.title}`);
          checkbox.addEventListener('change', async () => {
            try {
              await request(`/api/projects/${escapePath(id)}/tasks/${escapePath(task.id)}`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ completed: checkbox.checked }),
              });
              task.completed = checkbox.checked;
              renderTasks();
            } catch (error) {
              checkbox.checked = task.completed;
              alert.textContent = error.message;
              alert.hidden = false;
            }
          });
          const title = document.createElement('label');
          title.textContent = task.title;
          title.addEventListener('click', () => checkbox.click());
          row.append(checkbox, title);
          list.append(row);
        }
      }

      filter.addEventListener('change', renderTasks);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          return;
        }
        try {
          const task = await request(`/api/projects/${escapePath(id)}/tasks`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title }),
          });
          tasks.push(task);
          input.value = '';
          alert.textContent = '';
          alert.hidden = true;
          renderTasks();
        } catch (error) {
          alert.textContent = error.message;
          alert.hidden = false;
        }
      });
      app.append(back, heading, archivedNotice, renameForm, form, alert, tools, list);
      renderTasks();
    }

    const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
    try {
      if (match) await showProject(match[1]);
      else if (location.pathname === '/' || location.pathname === '') await showList();
      else app.textContent = 'Page not found';
    } catch {
      app.textContent = 'Project not found';
    }
  </script>
</body>
</html>

